int main() {
    char s[200005];
    scanf("%s", s);
    int n = strlen(s);
    long long count[200005];
    memset(count, 0, sizeof(count));

    // Find RL boundaries
    // For each RL boundary, count R's to the left (until previous RL boundary or start)
    // and L's to the right (until next RL boundary or end)

    int i = 0;
    while (i < n) {
        if (s[i] == 'R') {
            int j = i;
            while (j < n && s[j] == 'R') j++;
            // j is first L after this R block, or end
            if (j < n && s[j] == 'L') {
                int k = j;
                while (k < n && s[k] == 'L') k++;
                count[j-1] += (j - i);   // R's accumulate at last R
                count[j] += (k - j);     // L's accumulate at first L
                i = k;
            } else {
                i = j;
            }
        } else {
            i++;
        }
    }

    for (int i = 0; i < n; i++) {
        printf("%lld", count[i]);
        if (i < n-1) printf(" ");
    }
    printf("\n");
    return 0;
}

