int main(void) {
    static char s[200005];
    if (scanf("%s", s) != 1) return 0;

    int n = (int)strlen(s);
    static long long ans[200005];

    int i = 0;
    while (i < n) {
        if (s[i] == 'R') {
            int l = i;
            while (i < n && s[i] == 'R') i++;
            int r = i - 1;          // last R in this block

            int j = i;
            while (j < n && s[j] == 'L') j++;
            int l2 = i;             // first L in next block
            int r2 = j - 1;         // last L in this block

            int cntR = r - l + 1;
            int cntL = r2 - l2 + 1;

            // Boundary is between positions r (R) and l2 (L), and l2 == r + 1
            ans[r] += (cntR + 1) / 2 + cntL / 2;
            ans[l2] += cntR / 2 + (cntL + 1) / 2;

            i = j;
        } else {
            i++;
        }
    }

    for (int k = 0; k < n; k++) {
        if (k) putchar(' ');
        printf("%lld", ans[k]);
    }
    putchar('\n');

    return 0;
}

