int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;
    int n = s.size();
    vector<int> ans(n, 0);

    // For each position, find nearest L to the right and nearest R to the left
    vector<int> rightL(n, -1), leftR(n, -1);

    int lastL = -1;
    for (int i = n - 1; i >= 0; --i) {
        if (s[i] == 'L') lastL = i;
        rightL[i] = lastL;
    }

    int lastR = -1;
    for (int i = 0; i < n; ++i) {
        if (s[i] == 'R') lastR = i;
        leftR[i] = lastR;
    }

    for (int i = 0; i < n; ++i) {
        if (s[i] == 'R') {
            int target = rightL[i];
            int dist = target - i;
            if (dist % 2 == 0) ans[target]++;
            else ans[target - 1]++;
        } else { // 'L'
            int target = leftR[i];
            int dist = i - target;
            if (dist % 2 == 0) ans[target]++;
            else ans[target + 1]++;
        }
    }

    for (int i = 0; i < n; ++i) {
        cout << ans[i] << (i + 1 == n ? '\n' : ' ');
    }

    return 0;
}

