import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();
        int n = s.length();
        int[] ans = new int[n];

        // Find all RL boundaries
        for (int i = 0; i < n - 1; i++) {
            if (s.charAt(i) == 'R' && s.charAt(i + 1) == 'L') {
                ans[i]++;
                ans[i + 1]++;
            }
        }

        // Propagate counts from left to right for R segments
        int[] countR = new int[n];
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == 'R') {
                int cnt = 1;
                int j = i + 1;
                while (j < n && s.charAt(j) == 'R') {
                    cnt++;
                    j++;
                }
                // Now j is at 'L' or end
                int boundary = j - 1; // last R before L
                // distribute cnt children from i..boundary to the RL pair at boundary, boundary+1
                for (int k = i; k <= boundary; k++) {
                    int dist = boundary - k;
                    if (dist % 2 == 0) {
                        ans[boundary]++;
                    } else {
                        ans[boundary + 1]++;
                    }
                }
                i = boundary; // will be incremented by loop
            }
        }

        // Propagate counts from right to left for L segments
        for (int i = n - 1; i >= 0; i--) {
            if (s.charAt(i) == 'L') {
                int cnt = 1;
                int j = i - 1;
                while (j >= 0 && s.charAt(j) == 'L') {
                    cnt++;
                    j--;
                }
                int boundary = j + 1; // first L after R
                for (int k = i; k >= boundary; k--) {
                    int dist = k - boundary;
                    if (dist % 2 == 0) {
                        ans[boundary]++;
                    } else {
                        ans[boundary - 1]++;
                    }
                }
                i = boundary; // will be decremented by loop
            }
        }

        // Output results
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (i > 0) sb.append(" ");
            sb.append(ans[i]);
        }
        System.out.println(sb.toString());
    }
}

