                ans[i] = i - rStart + 1;
                ans[i+1] = lEnd - i;
                i = lEnd + 1;
            } else {
                i++;
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int j = 0; j < n; j++) {
            if (j > 0) sb.append(' ');
